 const string Source=CatalogPreparation.Root+"/Sources/SnowTownVehicles/",Logs="Logs/SnowTownVehicles",Request="Logs/ImportParkingVehicles.request";
 [Serializable]public class Pack{public Spec[] vehicles;}
 [Serializable]public class Spec{public string index,name;public int triangles,source_triangles,removed_zero_area,frontSign;}
 [Serializable]public class PlacedPose{public string id;public Vector3 position;public Quaternion rotation;}
 static T[] All<T>(Scene s)where T:Component=>s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<T>(true)).ToArray();
 static void Require(bool ok,string message){if(!ok)throw new InvalidOperationException("Parking intake: "+message);}
 [InitializeOnLoadMethod]static void Register(){EditorApplication.update+=Pending;}
 static void Pending(){if(!File.Exists(Request)){EditorApplication.update-=Pending;return;}if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;EditorApplication.update-=Pending;File.Delete(Request);try{Install();}catch(Exception e){Directory.CreateDirectory(Logs);File.WriteAllText(Logs+"/Validation.txt","FAIL: "+e);Debug.LogException(e);}}
 static Material Palette(){var path=Source+"ParkingPalette.mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Simple Lit")){name="Parked vehicles | shared opaque palette",enableInstancing=true};m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(Source+"Palette.png"));m.SetColor("_BaseColor",Color.white);m.SetColor("_SpecColor",Color.black);m.SetFloat("_Smoothness",0);m.SetFloat("_Cull",2);AssetDatabase.CreateAsset(m,path);}return m;}
 static Material Windows(){var path=Source+"ToonWindows.mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find(ToonWindowsAuthoring.ShaderName));AssetDatabase.CreateAsset(m,path);ToonWindowsAuthoring.Configure(m);}return m;}
 static CatalogAsset Prepare(Spec spec,Material snow){string id="parked-town-vehicle-"+spec.index;var a=CatalogPreparation.Library().Find(id);if(a&&a.prefab){CatalogPreparation.RecordMetrics(a);return a;}var path=Source+"Vehicle"+spec.index+".fbx";var importer=(ModelImporter)AssetImporter.GetAtPath(path);Require(importer!=null,"missing FBX "+spec.index);importer.globalScale=1;importer.importLights=false;importer.importCameras=false;importer.importAnimation=false;importer.isReadable=false;importer.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"ParkingBody"),Palette());importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"ParkingSnow"),snow);importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"ParkingGlazing"),Windows());importer.SaveAndReimport();var draft=CatalogPreparation.Draft(spec.name+" | parked",CatalogKind.Landscape,AssetSource.ImportedModel,null,"User supplied Snow_Town_Eight_Low_Poly_Vehicles.blend; SHA256 DB3F55EEF9EF1AC5A73BE398DB2C4EA26C6780EFA75678B6BC208FEB07404A62. Original preserved, studio ground/cameras/lights excluded, embedded scripts never executed. Static parked scenery only.");draft.id=id;draft.creationSourcePath="SourceAssets/SnowTownVehicles/Snow_Town_Eight_Low_Poly_Vehicles.blend";a=CatalogPreparation.Prepare(AssetDatabase.LoadAssetAtPath<GameObject>(path),CatalogKind.Landscape,spec.name+" | parked",1,Vector3.zero,AssetSource.ImportedModel,draft.provenance,draft);path=AssetDatabase.GetAssetPath(a.prefab);var root=PrefabUtility.LoadPrefabContents(path);
 try{var visual=root.transform.Find("VisualRoot");visual.localPosition=Vector3.zero;var raw=visual.GetChild(0);if(PrefabUtility.IsPartOfPrefabInstance(raw))PrefabUtility.UnpackPrefabInstance(PrefabUtility.GetOutermostPrefabInstanceRoot(raw.gameObject),PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);var frames=raw.GetComponentsInChildren<Transform>();var by=root.transform.InverseTransformPoint(frames.Single(t=>t.name=="BasisY").position);visual.localRotation=Quaternion.FromToRotation(by.normalized*spec.frontSign,Vector3.forward);foreach(var c in root.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c.gameObject);foreach(var r in root.GetComponentsInChildren<MeshRenderer>())r.sharedMaterial=r.name.StartsWith("Snow")?snow:r.name.StartsWith("Glazing")?Windows():Palette();foreach(var t in frames.Where(t=>t.name.StartsWith("Basis")))UnityEngine.Object.DestroyImmediate(t.gameObject);var bounds=CatalogValidation.BoundsOf(root);visual.localPosition-=Vector3.up*bounds.min.y;bounds=CatalogValidation.BoundsOf(root);var proxy=new GameObject("Collision | static parked vehicle");proxy.transform.SetParent(root.transform,false);var box=proxy.AddComponent<BoxCollider>();box.center=bounds.center;box.size=new Vector3(bounds.size.x*.98f,bounds.size.y*.95f,bounds.size.z*.98f);PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}
 a.tags=new[]{"parked-vehicle","static-scenery","removable-snow","opaque-toon-windows"};a.status=PreparationStatus.NeedsReview;a.visualReviewed=false;a.assumptions="Metres, grounded root, +Z front inferred from source headlamp surfaces. Static scenery: no Rigidbody, WheelCollider, vehicle controller or shop ownership. Prepared wheels combined into static Body; original blend preserves individual wheels. Snow and glazing separate. Three shared materials. Zero-area source faces removed, closed solids normalised outward. No lights, effects or runtime factories.";a.reviewNotes="Review parking collision and A07 costs before Ready publication.";CatalogPreparation.RecordMetrics(a);Require(a.triangles==spec.triangles,"triangles "+id+": "+a.triangles+" expected "+spec.triangles);EditorUtility.SetDirty(a);return a;}
 public static void PlacePrepared(Scene scene){Directory.CreateDirectory(Logs);var entries=new[]{1,2,3,5,8}.Select(i=>CatalogPreparation.Library().Find("parked-town-vehicle-"+i.ToString("D2"))).ToArray();if(entries.Any(a=>!a||!a.prefab))return;var originals=All<Transform>(scene).Where(t=>t.name=="Parked primitive car").OrderBy(t=>t.position.x).ThenBy(t=>t.position.z).ToArray();if(originals.Length==0)return;Require(originals.Length==5,"expected five parked primitives, found "+originals.Length);var roads=All<Renderer>(scene).Where(r=>r.name=="Road | asphalt").Select(r=>r.bounds).ToArray();var terrain=All<Terrain>(scene).Single();var records=new PlacedPose[5];for(int i=0;i<5;i++){var old=originals[i];var at=old.position;float y=terrain.SampleHeight(at)+terrain.transform.position.y;foreach(var road in roads)if(at.x>=road.min.x&&at.x<=road.max.x&&at.z>=road.min.z&&at.z<=road.max.z)y=Mathf.Max(y,road.max.y);at.y=y+.008f;var go=(GameObject)PrefabUtility.InstantiatePrefab(entries[i].prefab,scene);go.transform.SetParent(old.parent,true);go.transform.SetPositionAndRotation(at,old.rotation);var p=go.GetComponent<CatalogPlacement>();p.placementId="pinefall-parked-vehicle-"+(i+1).ToString("D2");PrefabUtility.RecordPrefabInstancePropertyModifications(p);PrefabUtility.RecordPrefabInstancePropertyModifications(go.transform);records[i]=new PlacedPose{id=p.placementId,position=old.position,rotation=old.rotation};UnityEngine.Object.DestroyImmediate(old.gameObject);}File.WriteAllText(Logs+"/OriginalParkingPoses.json",JsonUtility.ToJson(new PoseList{items=records},true));}
 [Serializable]class PoseList{public PlacedPose[] items;}
 static Bounds WorldBounds(GameObject go){var rs=go.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);return b;}
 static void Preview(GameObject go,string file,Vector3 direction){var p=new PreviewRenderUtility();try{var copy=UnityEngine.Object.Instantiate(go);copy.transform.position=Vector3.zero;p.AddSingleGO(copy);foreach(var t in copy.GetComponentsInChildren<WorldSignLabel>())t.Refresh();var b=WorldBounds(copy);p.camera.orthographic=true;p.camera.orthographicSize=Mathf.Max(b.extents.x,b.extents.y)*1.3f;p.camera.nearClipPlane=.1f;p.camera.farClipPlane=300;p.camera.transform.position=b.center+direction.normalized*80;p.camera.transform.LookAt(b.center);p.camera.backgroundColor=new Color(.3f,.4f,.47f);p.camera.clearFlags=CameraClearFlags.SolidColor;p.ambientColor=Color.gray;p.lights[0].intensity=1.2f;p.lights[0].transform.rotation=p.camera.transform.rotation;p.BeginStaticPreview(new Rect(0,0,1200,800));p.Render(true);var image=p.EndStaticPreview();File.WriteAllBytes(Logs+"/"+file+".png",image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);}finally{p.Cleanup();}}
 [MenuItem("Snowglow/Asset intake/Import eight parked town vehicles")]
 public static void Install(){Require(!EditorApplication.isPlayingOrWillChangePlaymode,"stop Play");var scene=SceneManager.GetActiveScene();Require(scene.path==SceneValidation.ScenePath,"open Pinefall");SceneValidation.Validate(scene);Directory.CreateDirectory(Logs);if(!File.Exists(Logs+"/Pinefall-before.unity"))EditorSceneManager.SaveScene(scene,Logs+"/Pinefall-before.unity",true);else if(scene.isDirty)EditorSceneManager.SaveScene(scene,Logs+"/Pinefall-unsaved-before.unity",true);var session=All<PrototypeSession>(scene).Single();var fleet=session.Fleet.Select(m=>AssetDatabase.GetAssetPath(PrefabUtility.GetCorrespondingObjectFromSource(m.gameObject))).ToArray();var snow=session.Snow;var original=snow.seed;var before=JsonUtility.ToJson(original.grid);var poses=All<CatalogPlacement>(scene).Where(p=>!string.IsNullOrEmpty(p.placementId)).ToDictionary(p=>GlobalObjectId.GetGlobalObjectIdSlow(p).ToString(),p=>p.transform.localToWorldMatrix.ToString("R"));var tex=(TextureImporter)AssetImporter.GetAtPath(Source+"Palette.png");tex.filterMode=FilterMode.Point;tex.wrapMode=TextureWrapMode.Clamp;tex.mipmapEnabled=false;tex.textureCompression=TextureImporterCompression.Uncompressed;tex.SaveAndReimport();var data=JsonUtility.FromJson<Pack>(File.ReadAllText(Source+"ExportMetrics.json"));var entries=data.vehicles.Select(v=>Prepare(v,snow.palette.snow)).ToArray();PlacePrepared(scene);Physics.SyncTransforms();var revised=UnityEngine.Object.Instantiate(original);int changed=0;for(int i=0;i<revised.grid.blocked.Length;i++){bool blocked=Physics.CheckBox(new Vector3(revised.grid.X(i),SnowField.Ground+.85f,revised.grid.Z(i)),new Vector3(SnowVolumeGrid.Cell*.45f,.65f,SnowVolumeGrid.Cell*.45f),Quaternion.identity,1<<0,QueryTriggerInteraction.Ignore);if(blocked!=revised.grid.blocked[i]){revised.grid.blocked[i]=blocked;changed++;}}if(changed>0){AssetDatabase.CreateAsset(revised,AssetDatabase.GenerateUniqueAssetPath(CatalogPreparation.Root+"/SceneData/ParkingVehiclesSnowObstacles.asset"));snow.seed=revised;EditorUtility.SetDirty(snow);}else UnityEngine.Object.DestroyImmediate(revised);AssetDatabase.SaveAssets();SceneValidation.Validate(scene);EditorSceneManager.MarkSceneDirty(scene);Require(EditorSceneManager.SaveScene(scene),"save failed");scene=EditorSceneManager.OpenScene(SceneValidation.ScenePath);SceneValidation.Validate(scene);MechanicsChecks.Run();session=All<PrototypeSession>(scene).Single();Require(fleet.SequenceEqual(session.Fleet.Select(m=>AssetDatabase.GetAssetPath(PrefabUtility.GetCorrespondingObjectFromSource(m.gameObject)))),"active machinery fleet changed");snow=session.Snow;var mask=snow.seed.grid.blocked;snow.seed.grid.blocked=original.grid.blocked;Require(before==JsonUtility.ToJson(snow.seed.grid),"snow quantities changed");snow.seed.grid.blocked=mask;foreach(var p in All<CatalogPlacement>(scene).Where(p=>poses.ContainsKey(GlobalObjectId.GetGlobalObjectIdSlow(p).ToString())))Require(poses[GlobalObjectId.GetGlobalObjectIdSlow(p).ToString()]==p.transform.localToWorldMatrix.ToString("R"),"existing pose changed");var placed=All<CatalogPlacement>(scene).Where(p=>(p.placementId??"").StartsWith("pinefall-parked-vehicle-")).OrderBy(p=>p.placementId).ToArray();Require(placed.Length==5&&!All<Transform>(scene).Any(t=>t.name=="Parked primitive car"),"five replacements required");var oldPoses=JsonUtility.FromJson<PoseList>(File.ReadAllText(Logs+"/OriginalParkingPoses.json"));foreach(var p in placed){var old=oldPoses.items.Single(x=>x.id==p.placementId);Require(Mathf.Abs(p.transform.position.x-old.position.x)<.001f&&Mathf.Abs(p.transform.position.z-old.position.z)<.001f&&Quaternion.Angle(p.transform.rotation,old.rotation)<.001f,"parking pose changed");Require(PrefabUtility.IsPartOfPrefabInstance(p)&&p.GetComponentInChildren<Rigidbody>()==null&&p.GetComponentInChildren<WheelCollider>()==null&&p.GetComponentInChildren<MachineController>()==null,"static scenery expected");}
 foreach(var spec in data.vehicles){var entry=CatalogPreparation.Library().Find("parked-town-vehicle-"+spec.index);Preview(entry.prefab,"Vehicle-"+spec.index,new Vector3(.6f,.3f,1));}
 var context=new GameObject("Parking preview");context.transform.position=placed[2].transform.position;try{foreach(var p in placed){var copy=UnityEngine.Object.Instantiate(p.gameObject);copy.transform.SetParent(context.transform,true);}Preview(context,"Parking-row",new Vector3(.3f,.65f,1));}finally{UnityEngine.Object.DestroyImmediate(context);}
 File.WriteAllText(Logs+"/Validation.txt","PASS: Unity "+Application.unityVersion+" / "+EditorUserBuildSettings.activeBuildTarget+". Eight Needs Review static parked catalog variants. Replaced all five primitive parked cars with hatchback/sedan/pickup/SUV/taxi, retaining X/Z/headings and seating tyres on the parking surface. 13344 placed triangles, 15 renderers, three shared materials (opaque palette/toon snow/opaque cyan toon windows). "+changed+" obstacle flags refreshed in separate seed if needed; snow quantities and existing catalog poses retained. Active machinery fleet unchanged, no new driving/ownership. Scene saved/reopened; scene validation/19 snow checks passed. Eight variant and one row renders written. No district rebake/player-save writes. Actual driving/Android/A07 performance untested.");Debug.Log(File.ReadAllText(Logs+"/Validation.txt"));}
